/*
 * A262903  Numbers that are not leaves but all of whose children are leaves
 *          in the tree generated by edge-relation A049820(child) = parent.
 * https://oeis.org/A262903
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n-th number m such that A049820(c)=m has at least one
 *            solution c and every such c has no children itself; computed by
 *            divisor sieve + doubling search
 * Range:     u8 n <= 29, u16 n <= 9383, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 102 terms through n = 9501 (2026-11-07)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

static uint32_t *g_terms = 0;
static size_t g_cnt = 0;

static void A262903_build(uint64_t limit)
{
    uint64_t r = 1;
    while (r * r <= limit) r++;
    uint64_t S = limit + 4 * r + 40;
    uint32_t *d = (uint32_t *)calloc((size_t)S + 1, sizeof(uint32_t));
    uint32_t *cc = (uint32_t *)calloc((size_t)S + 1, sizeof(uint32_t));
    uint32_t *terms = (uint32_t *)malloc(sizeof(uint32_t) * ((size_t)limit + 1));
    size_t cnt = 0;
    uint64_t i, j, c, m;
    for (i = 1; i <= S; i++)
        for (j = i; j <= S; j += i) d[j]++;
    for (c = 1; c <= S; c++) {
        m = c - d[c];
        if (m >= 1) cc[m]++;
    }
    for (m = 1; m <= limit; m++) {
        if (cc[m] == 0) continue;
        uint64_t hi = m + 2 * r + 8;
        int ok = 1;
        if (hi > S) hi = S;
        for (c = m + 1; c <= hi; c++) {
            if (c - d[c] == m && cc[c] > 0) { ok = 0; break; }
        }
        if (ok) terms[cnt++] = (uint32_t)m;
    }
    free(d);
    free(cc);
    if (g_terms) free(g_terms);
    g_terms = terms;
    g_cnt = cnt;
}

seq_t a(idx_t n)
{
    if (n < 1) return 0;
    if (g_cnt < (size_t)n) {
        uint64_t limit = 1000;
        if (limit < 20 * (uint64_t)n) limit = 20 * (uint64_t)n;
        if (g_terms && limit < 2 * (g_cnt ? (uint64_t)g_terms[g_cnt - 1] : 0))
            limit = 2 * (uint64_t)g_terms[g_cnt - 1];
        for (;;) {
            A262903_build(limit);
            if (g_cnt >= (size_t)n) break;
            limit *= 2;
        }
    }
    return (seq_t)g_terms[n - 1];
}
